import { Component, ElementRef, Input, Output, EventEmitter, ViewChild, OnInit, AfterViewInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { User } from '../../../../core/models/user';

@Component({
  selector: 'app-create-contribution',
  standalone: false,
  templateUrl: './create-contribution.component.html',
  styleUrl: './create-contribution.component.css'
})
export class CreateContributionComponent implements OnInit {

  @Input() allPoliticians: User[] = [];
  @Input() followedPoliticians: User[] = [];

  @Output() submitMarkedPoliticians = new EventEmitter<User[]>();
  @Output() submitContributionText = new EventEmitter<string>();
  @Output() submitSupport = new EventEmitter<boolean | null>();

  contributionForm!: FormGroup;

  markedPoliticians: User[] = [];

  contributionText = '';
  isBold = false;
  isItalic = false;
  isSupported: boolean | null = null;
  isPulsing = {
    support: false,
    oppose: false
  };
  showSelectBox = false;
  searchTerm: string = '';

  constructor(private fb: FormBuilder) { }

  ngOnInit() {
    this.contributionForm = this.fb.group({
      contributionText: ['', Validators.required],
    });
  }

  setSupport(value: boolean) {
    this.isSupported = value;

    const key = value ? 'support' : 'oppose';
    this.isPulsing[key] = true;

    setTimeout(() => {
      this.isPulsing[key] = false;
    }, 300);
  }

  handleMarkedPoliticiansChange(politicians: User[]) {
    this.markedPoliticians = politicians;
  }

  handleContributionTextChange(text: string) {
    this.contributionText = text;
  }

  submitContribution() {
    this.submitContributionText.emit(this.contributionText);
    this.submitMarkedPoliticians.emit(this.markedPoliticians);
    this.submitSupport.emit(this.isSupported);

    this.markedPoliticians = [];
    this.isSupported = null;
    this.isBold = false;
    this.isItalic = false;
  }
}

import { Component, EventEmitter, Input, Output } from '@angular/core';
import { DebateContribution } from '../../../../core/models/debate-contribution';

@Component({
  selector: 'app-debate-contribution',
  standalone: false,
  templateUrl: './debate-contribution.component.html',
  styleUrl: './debate-contribution.component.css'
})
export class DebateContributionComponent {
  @Input()
  debateContribution!: DebateContribution;
  @Input()
  small?: boolean = false;

  @Output()
  reaction = new EventEmitter<string>();

  tie = ""
  showFullText: boolean = false;

  onClickReact(reaction: "up" | "down" | undefined) {
    const currentReaction = this.debateContribution.userReaction;

    if (currentReaction === reaction) {
      this.reaction.emit(undefined);
      if (reaction === "up") this.debateContribution.ups--;
      if (reaction === "down") this.debateContribution.downs--;
      this.debateContribution.userReaction = undefined;
    } else {
      if (currentReaction === "up") this.debateContribution.ups--;
      if (currentReaction === "down") this.debateContribution.downs--;
      if (reaction === "up") this.debateContribution.ups++;
      if (reaction === "down") this.debateContribution.downs++;
      this.reaction.emit(reaction);
      this.debateContribution.userReaction = reaction;
    }
  }

  get displayText(): string {
    const text = this.debateContribution.text;
    return this.showFullText || text.length <= 500 ? text : text.slice(0, 500) + '...';
  }

  toggleText(): void {
    this.showFullText = !this.showFullText;
  }
}

